"""Port of kotlin.random.Random(seed: Int) (XorWow), checked against fixtures/kotlin_random.json (generated by the Kotlin code)."""
import numpy as np

M = 0xFFFFFFFF


def _s32(x):
    x &= M
    return x - (1 << 32) if x & 0x80000000 else x


class XorWow:
    def __init__(self, seed):
        seed = _s32(seed)
        seed1, seed2 = seed, seed >> 31  # arithmetic shift as in Kotlin (Int.shr)
        self.x = seed1 & M
        self.y = seed2 & M
        self.z = 0
        self.w = 0
        self.v = (~seed1) & M
        self.addend = ((seed1 << 10) ^ ((seed2 & M) >> 4)) & M
        if (self.x | self.y | self.z | self.w | self.v) == 0:
            raise ValueError("illegal seed")
        for _ in range(64):
            self.next_int_u()

    def next_int_u(self):
        """Unsigned 32-bit nextInt()."""
        t = self.x
        t ^= t >> 2
        self.x, self.y, self.z = self.y, self.z, self.w
        v0 = self.v
        self.w = v0
        t = ((t ^ ((t << 1) & M)) ^ v0 ^ ((v0 << 4) & M)) & M
        self.v = t
        self.addend = (self.addend + 362437) & M
        return (t + self.addend) & M

    def next_int(self):
        return _s32(self.next_int_u())

    def next_float(self):
        """nextFloat() = nextBits(24) / 2^24 (exact in float32)."""
        return (self.next_int_u() >> 8) / float(1 << 24)

    def floats(self, n):
        out = np.empty(n, dtype=np.float64)
        for i in range(n):
            out[i] = self.next_int_u() >> 8
        return (out / float(1 << 24)).astype(np.float32)


def kotlin_unit_vector(seed, dim=384):
    """Test vector used by the Kotlin fixtures: Random(seed) floats in [-1, 1), L2-normalised exactly as the Kotlin helper
    (double sum of float32 squares, sqrt, toFloat, float32 division)."""
    r = XorWow(seed)
    v = r.floats(dim) * np.float32(2) - np.float32(1)
    sq = (v * v).astype(np.float64)
    n = np.float32(np.sqrt(np.cumsum(sq)[-1]))
    return (v / n).astype(np.float32)
